import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class Main {
    public static void main(String[] args) {
        LocalDate d = LocalDate.of(2026, 9, 16);
        LocalDate later = d.plusDays(5);

        System.out.println(d);
        System.out.println(later);
        System.out.println(later.format(DateTimeFormatter.ofPattern("MM月dd日")));
    }
}

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate start = LocalDate.of(2026, 9, 1);
        LocalDate end = LocalDate.of(2026, 9, 16);

        System.out.println(ChronoUnit.DAYS.between(start, end));
        System.out.println(end.isAfter(start));
        System.out.println(start.getDayOfWeek());
        System.out.println(start.lengthOfMonth());
    }
}
